\label{thm: mainthm} Let $d\in {\mathbb N}$ with $d\geq 3$ and $Q\in (d,\frac{d(d-1)+2}{2}]$. There exists a nonempty collection $\mathcal{F}$ of pointed metric measure manifolds so that each $M\in \mathcal{F}$ is isomorphic to some $({\mathbb R}^d,\mathbf{d},\mu, \mathbf{0})$ satisfying:
\begin{enumerate} 
\item $({\mathbb R}^d,\mathbf{d})$ is a  complete geodesic metric space, that is linearly locally contractible and whose distance induces the standard topology of ${\mathbb R}^d$,
\item $\mu$ is equal to a multiple of the Lebesgue measure on ${\mathbb R}^d$,
\item $\mu$ is $Q$-Ahlfors regular with respect to $\mathbf{d}$, 
\item $M$ has analytic dimension $2$, and
\item $M$ satisfies a Poincar\'e inequality,
\end{enumerate}
and $\mathcal{F}$ has the properties:
\begin{enumerate}
 \item[(6)] $\mathcal{F}$ is invariant under scalings and changes of basepoints, and
 \item[(7)] $\mathcal{F}$ is compact with respect to pointed measured Gromov-Hausdorff convergence.
\end{enumerate}

\label{cor:tangents} 
 Every family $\mathcal{F} $ with the properties of Theorem~\ref{thm: mainthm} is such that
 for every $M\in \mathcal{F}$, every weak tangent of $M$ is in $\mathcal{F}$.

The class $\mathcal{F}^{\rm reg}_{C,\alpha}$ is simple to define and leads to a family of $Q$-Ahlfors regular spaces with $Q$ given above. Once $Q>\frac{d(d-1)+2}{2}$, it is harder to define a class of functions, that is compact, such that each function in the collection corresponds to a space that has $\mu$-essential Hausdorff dimension $Q$, and every positive measure subset has Hausdorff dimension at least $Q$. This is mostly a technical challenge, and a possible condition is the following. Let $\alpha =\frac{2(Q-d)}{(d-2)(d-1)}$. Take any continuous  increasing function $\phi:[0,1]\to[0,\infty)$ with $\lim_{t\to 0}\phi(t)= 0$,  $\epsilon,\delta \in (0,1)$ and
\begin{align*}
&\mathcal{F}_{\phi,Q,D}=\Big\{f\in \mathcal{F}^{\rm doubl}_{D,\epsilon,\delta} : \forall I\subset {\mathbb R}, r\in (0,1)\\
& \ \ \lambda\left\{x\in I : \forall s\in (0,r|I|),  \left(\frac{2s}{|I|}\right)^{\alpha+\phi(r)} \leq \frac{\operatorname{osc}(f,[x-s,x+s])}{\operatorname{osc}(f,I)} \leq \left(\frac{2s}{|I|}\right)^{\alpha-\phi(r)}\right\} \geq (1-\phi(r)) |I| \Big\}.
\end{align*}
See Section~\ref{sec: GH} for the definition of $\mathcal{F}^{\rm doubl}_{D}$. It follows fairly directly from Lemma~\ref{lem: billinglsey} and the proof of Theorem~\ref{thm: mainthm2} that any $f\in \mathcal{F}_{\phi,Q,D}$ yields a space $({\mathbb R}^d,\mathbf{d}_f, \lambda, \mathbf{0})$ satisfying the conclusions in Theorem~\ref{thm: mainthm2}. Moreover, this class of functions is invariant under translations and scalings, and thus the proof of Lemma~\ref{lem: convergence} shows that the associated collection of spaces is compact with respect to the pointed measured Gromov-Hausdorff convergence and invariant under scalings and changes of basepoints. Thus, this class of spaces is also closed under taking weak tangents. The class is non-empty for some $\phi$ by the constructions in Section~\ref{sec: doublingfunctions}.

\label{cor:subseq}
    Consider a continuous Carnot-Carathéodory structure $(M,\Delta,\|\cdot\|)$ equipped with its associated CC metric $d_{\Delta,\|\cdot\|}$.
    \begin{enumerate}
    \item 
    Every point admits a neighborhood $U$ such that each sequence of curves in $U$ with a common starting point and uniformly bounded CC-length has, 
    after reparametrizing on $[0,1]$ with bounded speed,
      a subsequence that
    converges uniformly with respect to the manifold topology.




        \item If $\boldsymbol{\gamma}_n: I\to M$, for $n\in {\mathbb N}$, is a sequence of curves that have uniformly bounded CC-speed and are converging uniformly with respect to the manifold topology to a curve $ \boldsymbol{\gamma}: I\to M$, then the curve
        $\boldsymbol{\gamma}$ is $\Delta$-horizontal and 
         the length structure from \eqref{def_CC_length} satisfies
         \begin{equation}
            \label{eq limits of lenths}
         {\rm L}_{\|\cdot\|} (\boldsymbol{\gamma}) \leq \liminf_{n\to \infty}  {\rm L}_{\|\cdot\|} (\boldsymbol{\gamma}_n). \end{equation}
          \item The metric space $(M,d_{\Delta,\|\cdot\|} ) $ is locally geodesic, i.e.,  every point $\mathbf{p}\in M$ has a neighborhood $B_{d_{\Delta,\|\cdot\|}}(\mathbf{p},r)$ where each pair of points can be connected by a curve in $M$ whose length equals the distance of the pair. 
          \item The distance $d_{\Delta,\|\cdot\|}$ is an inner distance.
          \item The metric space $(M, d_{\Delta,\|\cdot\|})$ is locally complete.
    \end{enumerate}

\label{lem:limcurvehorizontal} 
Let $(M,\Delta_n,\|\cdot\|_n)_{n\in {\mathbb N}} $  be a sequence of continuous Carnot-Carath\'eodory structures that are
continuously converging to a continuous Carnot-Carath\'eodory structure $(M,\Delta,\|\cdot\|) $.
For $n\in {\mathbb N}$, let $\boldsymbol{\gamma}_n:I\to M$ be a curve.
Assume that the sequence of horizontal curves $(\boldsymbol{\gamma}_n)_{n\in{\mathbb N}}$ has uniformly bounded $CC$-speed for $(\Delta_n,\|\cdot\|_n)$ and that it converges uniformly to an absolutely continuous curve $\boldsymbol{\gamma}: I\to M$, with respect to the topology of $M$.

Then $\boldsymbol{\gamma}$ is $\Delta$-horizontal and 
         the length structure from \eqref{def_CC_length} satisfies
        \begin{equation}
            \label{eq limits of lenths - varying}
         {\rm L}_{\|\cdot\|} (\boldsymbol{\gamma}) \leq \liminf_{n\to \infty}  {\rm L}_{\|\cdot\|_n} (\boldsymbol{\gamma}_n). \end{equation}

\label{rmk endpoint}

For all $f \in C^0(\mathbb{R})$ and all $d > 2$, the endpoint map for the structure given by  
 $\mathbf{X},\mathbf{Y}$ as in \eqref{eq:vectdef}
 is well-defined. Namely, for all $a, b : [0, 1] \to \mathbb{R}$ integrable and for all $\mathbf{p} \in \mathbb{R}^d$, there exists a unique absolutely continuous curve $\gamma : [0, 1] \to \mathbb{R}^d$ such that 
\[
\begin{cases} 
\gamma(0) = \mathbf{p} \\
\dot{\gamma} = a \mathbf{X}(\gamma) + b \mathbf{Y}(\gamma) .
\end{cases}
\]
In fact, writing $\gamma = (\gamma_1, \dots, \gamma_d)$, the ODE becomes 
\[
(\dot{\gamma}_1, \dots, \dot{\gamma}_d) = \left( a, b, b \cdot (f \circ \gamma_1), \dots, b \cdot (f \circ \gamma_1)^{d-2} \right).
\]
Thus, writing $\mathbf{p} = (p_1, \dots, p_d)$, we integrate the first component: 
\begin{equation}\label{first component}
\gamma_1(t) = p_1 + \int_0^t a(s) \, {\rm{d}} s
\end{equation}
and then the rest:
\begin{equation}\label{second components}
\gamma_i(t) = p_i + \int_0^t b(s) \left( f \left( p_1 + \int_0^s a(\tau) \, {\rm{d}}\tau \right) \right)^{i-2} {\rm{d}} s, \qquad \forall i \in \{2, \dots, d\},
\end{equation}
which is integrable because $a, b$ are so, and $f$ is continuous. 
In addition, notice that if $f_n \in C^0(\mathbb{R})$ is a sequence that converges locally uniformly to $f \in C^0(\mathbb{R})$, then, fixed $a, b$, we get that the sequence of points $\gamma(1)$ associated to $f_n$ converges to the point $\gamma(1)$ associated to $f$.

\label{lem: simpleflow}
Let $\mathbf{p}=(p_1,\mathbf{p}_{-1} )\in {\mathbb R}^d$ and $f:{\mathbb R}\to {\mathbb R}$.
\begin{enumerate}
\item                            
For $\mathbf{y}\in {\mathbb R}^{d-1}$, and $\mathbf{t}\in {\mathbb R}^{d}$,
the associated point $\mathbf{p}^{d+1}$ constructed in \eqref{some points} using \eqref{eq:vectdef} satisfies 
\begin{equation}\label{Madrid19052026_15}
\mathbf{p}^{d+1}=
\mathbf{p} + (t_{d},{\bf Van}(f(p_1+t_1), \dots f(p_1+t_{d-1}))\mathbf{y}).
\end{equation}
\item                            
Let $\mathbf{q} =(q_1,\mathbf{q}_{-1})\in {\mathbb R}^d$, $(t_1,\dots, t_{d-1})\in {\mathbb R}^{d-1}$. Assume that $\mathbf{V}:={\bf Van}(f(p_1+t_1), \dots f(p_1+t_{d-1}))$ is invertible and put 
$\mathbf{y}:=\mathbf{V}^{-1}(\mathbf{q}_{-1}-\mathbf{p}_{-1})$, and $t_d:=q_1-p_1$. Then, the  points   in \eqref{some points} associated to $\mathbf{t}$, $\mathbf{y}$, and $\mathbf{p}$ give $\mathbf{p}^{d+1}=\mathbf{q}$ and consequently
\begin{equation}\label{Madrid19052026_16}
\mathbf{d}(\mathbf{p},\mathbf{q})\leq |p_1-q_1| + 2d \left(\max_{i\in \{1,\dots,d-1\}}|t_i|\right) +d \left |\mathbf{V}^{-1}(\mathbf{q}_{-1}-\mathbf{p}_{-1})\right|.
\end{equation}
\end{enumerate}

\label{lem: distest} Let $f:{\mathbb R}\to {\mathbb R}$ be continuous.  Let $\mathbf{p}= (p_1, \mathbf{p}_{-1}), \mathbf{q}= (q_1, \mathbf{q}_{-1} )\in {\mathbb R}\times{\mathbb R}^{d-1}$. 



\begin{enumerate}
 \item If $f:{\mathbb R}\to {\mathbb R}$ is constant, then $\mathbf{d}(\mathbf{p},\mathbf{q})=\infty$ unless $\mathbf{q}-\mathbf{p}=(t,s,f(p_1)s, \dots, f(p_1)^{d-2}s)$ for some $t,s\in {\mathbb R}$. 

 \item If for some interval $I\subset {\mathbb R}$ the function $f$ is constant on $2I$ and $p_1,q_1\in I$, then $\mathbf{d}(\mathbf{p},\mathbf{q})\geq |I|$ unless $\mathbf{q}_{-1}-\mathbf{p}_{-1}=(s,f(p_1)s, \dots, f(p_1)^{d-2}s)$ for some $s\in {\mathbb R}$. 

 \item Assume that $I\subset {\mathbb R}$ is an interval and that $\delta:=\operatorname{osc}(f,2I)>0$.                                
 Assume $p_1,q_1\in I$, 
  and $s_1,\dots, s_{d-1}\in 2I$

 are such that $f(s_i)\neq f(s_j)$ for all distinct $i,j\in \{1,\ldots,d-1\}$. Let $\mathbf{V}:={\bf Van}(f(s_1),\dots, f(s_{d-1} ))$. Then, we have
 \begin{multline}\label{eq bounds for d}
 \min\left(|I|, 
 \frac{1}{2}|p_1-q_1|+\frac{1}{2d}\left|\mathbf{D}_{\delta^{-1}}\mathbf{L}_{f(p_1)}(\mathbf{q}_{-1}-\mathbf{p}_{-1})\right|\right)\leq \mathbf{d}(\mathbf{p},
 \mathbf{q})\\
 \leq (4 d + 1) |I|  +d\left|\mathbf{V}^{-1}(\mathbf{q}_{-1}-\mathbf{p}_{-1})\right|.
 \end{multline}
Moreover, if $(s_i)_{i=1}^{d-1}$ are chosen so that $(f(s_i))_{i=1}^{d-1}$ forms an equi-partition of $f(2I)$, then there exists a constant $C_d\geq 1$ depending only on $d$, for which 
 \begin{equation}\label{eq another bounds for d}
\mathbf{d}(\mathbf{p},
 \mathbf{q})\leq C_d  \left(|I| +   \left|\mathbf{D}_{\delta}^{-1}\mathbf{L}_{f(p_1)}(\mathbf{q}_{-1}-\mathbf{p}_{-1})\right| \right) .
 \end{equation}
 \end{enumerate}

\label{lem: characterization}
 The function $\mathbf{d}$ in \eqref{eq:metricdef} is a distance function  such that on every compact set there exists $C>0$ such that $\mathbf{d}_{\rm eucl}\leq C \mathbf{d}$. The metric space $({\mathbb R}^d,\mathbf{d}_f)$ is a length space. 
 The distance function is finite-valued if and only if $f$ is not constant. This distance function induces the standard topology of ${\mathbb R}^d$ if and only if $f$ has positive oscillation.

\label{lem:doublingpart}
    Given $d\in {\mathbb N}$ with $d\geq 3$ and $f:{\mathbb R}\to {\mathbb R}$ continuous, let 
$({\mathbb R}^d,\mathbf{d}_f,\lambda)$ be the metric measure space, where $\mathbf{d}_f$ is defined in \eqref{eq:metricdef} via the vector fields \eqref{eq:vectdef}, and $\lambda$ is the Lebesgue measure.
If $f $ has doubling oscillation, then 
$({\mathbb R}^d,\mathbf{d}_f,\lambda)$ is LLC and doubling, and there exists a constant $C\geq 1$ such that  for every $\mathbf{p}=(p_1,\mathbf{p}_{-1})\in {\mathbb R}^d$ 
\begin{equation}
\label{eq measure expansion}
C^{-1} r^d \rho^{\frac{(d-2)(d-1)}{2}} \leq \lambda(B(\mathbf{p},r))\leq C r^d \rho^{\frac{(d-2)(d-1)}{2}}, \qquad \forall\mathbf{p}\in {\mathbb R}^d \ \  \forall r>0
\end{equation}
with $\rho=\operatorname{osc}(f,[p_1-r,p_1+r])$. Moreover, if $f$ has $\alpha$-regular oscillation then $\lambda$ is $Q$-Ahlfors regular with $Q=d+\frac{(d-2)(d-1)}{2}\alpha$.

\label{lem: billinglsey} 
Let $Q\in (0,\infty)$. Let $(X,d)$ be a doubling metric space and $\mu$ a non-zero Radon measure.
\begin{enumerate}
\item If $\mu$ is $Q$-Ahlfors regular, then $X$ has Hausdorff dimension $Q$ and $\mu$ has essential Hausdorff dimension $Q$.

\item If for $\mu$-a.e. $\mathbf{p}\in X$ the measure satisfies 
\[
\lim_{r\to 0}\frac{\log(\mu(B(\mathbf{p},r)))}{\log(r)}=Q
\]
then $\mu$ has essential Hausdorff dimension $Q$. 
\end{enumerate}

\label{thm:lanconelli}

Let $({\mathbb R}^d, \Delta, \|\cdot\|)$ be a continuous Carnot-Carath\'eodory structure


and let $\lambda$ be the Lebesgue measure.
Let $B:=B(\mathbf{p},r)\subset {\mathbb R}^d$ be a ball with respect to $d_{\Delta,\|\cdot \|}$. 
Let $\Omega\subset B$ be open and bounded, and let $Q\subset {\mathbb R}^d$ be a bounded neighborhood of ${\bf 0}\in {\mathbb R}^d$. 
Assume that there exists an almost exponential map $E:\Omega\times Q\to {\mathbb R}^d$ and two constants $\alpha,\beta>0$ for which we have the following:
\begin{enumerate}
\item $\lambda(B)\leq \alpha \lambda(\Omega)$ and $B\subset E(x,Q)$ for every $x\in \Omega$,
\item $E$ is controllable with hitting time $T\leq \alpha r$, and
\item $\lambda((\alpha+1)B)\leq \beta \lambda(B)$.
\end{enumerate}
Then, there exists some $c>0$, which depends only on $\alpha,\beta$ and the constants $a,b$ above, such that for each $d_{\Delta,\|\cdot \|}$-Lipschitz function $u: (\alpha+1)B \to {\mathbb R}$  one has
\begin{equation}\label{eq:weakPI}
\int_B\int_{B} |u(\mathbf{x})-u(\mathbf{y})|{\rm{d}}\lambda {\rm{d}}\lambda \leq cr \lambda(B) \int_{(\alpha+1)B} \operatorname{Lip}_{d_{\Delta,\|\cdot \|}}[u] {\rm{d}}\lambda.
\end{equation}

Fix $B, u, E, \Omega$ as in the statement. The claim is obvious if $\lambda(B)=0$, and thus we assume that $\lambda(B)>0$. By controllability, it is easy to see that $E(x, Q)\subset (\alpha+1)B$. From this, we get
\begin{align*}
   \lambda(Q) D(\mathbf{x},0)\leq a \int_Q D(\mathbf{x},h) d\lambda \leq a \lambda((\alpha+1)B)\leq a\beta \lambda(B).
\end{align*}
Thus, 
\begin{equation}\label{eq:jacobest}
D(\mathbf{x},0)\leq \frac{a\beta \lambda(B)}{\lambda(Q)}.
\end{equation}
First, by using a change of variables and the estimate for $D(\mathbf{x}, \mathbf{h})$, we get:
\begin{align*}
    \int\int_{B\times B} |u(\mathbf{x})-u(\mathbf{y})|{\rm{d}}\lambda_{\mathbf{x}} {\rm{d}}\lambda_{\mathbf{y}} &\leq 2 \int\int_{B\times B} |u(\mathbf{x})-u_\Omega|{\rm{d}}\lambda_{\mathbf{x}} {\rm{d}}\lambda_{\mathbf{y}} \\
    & \leq \frac{2\lambda(B)}{\lambda(\Omega)}\int\int_{\Omega\times B} |u(\mathbf{x})-u(\mathbf{y})|{\rm{d}}\lambda_{\mathbf{x}} {\rm{d}}\lambda_{\mathbf{y}} \\
    & \leq \frac{2\lambda(B)}{\lambda(\Omega)}\int_{\Omega} \int_{Q} |u(E(\mathbf{x},0))-u(E(\mathbf{x},\mathbf{h}))|D(\mathbf{x},\mathbf{h}){\rm{d}}\lambda_{\mathbf{h}} {\rm{d}}\lambda_{\mathbf{x}}
    \end{align*}
Next, we drop the subscript and write $\operatorname{Lip}[u]$ to streamline the calculations below.
The function $t\to u(\gamma(\mathbf{x},\mathbf{h},t))$ is Lipschitz by assumption and since $\|\dot\gamma(\mathbf{x},\mathbf{h},s)\|\leq 1$ we get
\[
|u(E(\mathbf{x},\mathbf{h}))-u(E(\mathbf{x},0))| \leq \int_{0}^T |u(\gamma(\mathbf{x},\mathbf{h},\cdot))'(s)| {\rm{d}} s \leq \int_{0}^T \operatorname{Lip}[u](\gamma(\mathbf{x},\mathbf{h},s)) {\rm{d}} s.
\]
    Substituting this into the previous integral and using Fubini yields
    \begin{align*}
    \int\int_{B\times B} |u(\mathbf{x})-u(\mathbf{y})|{\rm{d}}\lambda_{\mathbf{x}} {\rm{d}}\lambda_{\mathbf{y}} &\stackrel{\rm Ass. \ (1)}{\leq} 2a \alpha\int_{\Omega} \int_{Q} \int_{0}^T \operatorname{Lip}[u](\gamma(\mathbf{x},\mathbf{h},s)) {\rm{d}} s {\rm{d}}\lambda_\mathbf{h} D(\mathbf{x},0){\rm{d}}\lambda_{\mathbf{x}} \\
    &\stackrel{\eqref{eq:jacobest}}{\leq} \frac{2 a^2\alpha \beta \lambda(B)}{\lambda(Q)}\int_{\Omega} \int_{Q} \int_{0}^T \operatorname{Lip}[u](\gamma(\mathbf{x},\mathbf{h},s)) {\rm{d}} s {\rm{d}}\lambda_\mathbf{h} {\rm{d}}\lambda_{\mathbf{x}} \\
    & = \frac{2 a^2\alpha \beta \lambda(B)}{\lambda(Q)} \int_{Q} \int_{0}^T  \int_{\Omega} \operatorname{Lip}[u](\gamma(\mathbf{x},\mathbf{h},s)) {\rm{d}}\lambda_{\mathbf{x}} {\rm{d}} s {\rm{d}}\lambda_\mathbf{h} \\
     & \stackrel{\eqref{eq:jacobianphi}}{\leq} \frac{2 a^2\alpha \beta \lambda(B)}{b\lambda(Q)} \int_{Q} \int_{0}^T  \int_{(\alpha+1)B} \operatorname{Lip}[u](\mathbf{x}) {\rm{d}}\lambda_{\mathbf{x}} {\rm{d}} s {\rm{d}}\lambda_\mathbf{h} \\
     & \leq 2 a^2\alpha^2 \beta b^{-1} r \lambda(B) \int_{(\alpha+1)B} \operatorname{Lip}[u] {\rm{d}}\lambda.
\end{align*}
   This yields the desired claim.

\label{def:diffspace} A separable metric measure space $(X,\mathbf{d},\mu)$ (with $\mathbf{d}(x,y)<\infty$ for every $x,y\in X$) is said to be a {\em Lipschitz differentiability space}, if there exist countably many measurable positive-measure sets $U_i\subseteq X$, $i\in {\mathbb N}$, with $\mu(X\setminus \bigcup_{i\in {\mathbb N}} U_i)=0$, and Lipschitz functions $\phi_i:X\to {\mathbb R}^{n_i}$, for some $n_i\in {\mathbb N}$, for which for every Lipschitz function $f:X\to {\mathbb R}$ and every $i\in {\mathbb N}$ for a.e. $\mathbf{x}\in U_i$ there exists a unique linear map ${\rm{d}} f_{i,\mathbf{x}}:{\mathbb R}^{n_i}\to {\mathbb R}$ for which
\begin{equation}\label{eq:diff}
\operatorname{Lip}[f(\cdot)-{\rm{d}} f_{i,\mathbf{x}}\circ \phi_i(\cdot)](\mathbf{x})=0.
\end{equation}
